const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const {candidates}=require('../src/hancom-discovery.cjs'),{resolvePython,pythonEnvironment}=require('../src/runtime-python.cjs');
test('Hangul discovery supports multiple Office folders and chooses newer versions first without launching apps',()=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'narae-discovery-'));try{for(const dir of ['Office 2020/HOffice110/Bin','Office 2022/HOffice120/Bin','Office 2024/HOffice130/Bin','Office 2026/HOffice140/Bin']){fs.mkdirSync(path.join(root,dir),{recursive:true});fs.writeFileSync(path.join(root,dir,'Hwp.exe'),'fixture');}const result=candidates([root]);assert.equal(result.length,4);assert.match(result[0],/2026/);assert.match(result[3],/2020/);}finally{assert(path.dirname(root)===os.tmpdir());fs.rmSync(root,{recursive:true,force:true});}});
test('app Python runtime is preferred and inherited Python search paths are not used',()=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'narae-runtime-'));const prior=process.env.NARAE_OFFICE_PYTHON;try{delete process.env.NARAE_OFFICE_PYTHON;fs.mkdirSync(path.join(root,'runtime/python'),{recursive:true});fs.writeFileSync(path.join(root,'runtime/python/python.exe'),'fixture');assert.equal(resolvePython(root),path.join(root,'runtime/python/python.exe'));process.env.PYTHONHOME='foreign';process.env.PYTHONPATH='foreign';const env=pythonEnvironment(root);assert(!env.PYTHONHOME);assert(!env.PYTHONPATH);assert.equal(env.PYTHONNOUSERSITE,'1');}finally{delete process.env.PYTHONHOME;delete process.env.PYTHONPATH;if(prior===undefined)delete process.env.NARAE_OFFICE_PYTHON;else process.env.NARAE_OFFICE_PYTHON=prior;assert(path.dirname(root)===os.tmpdir());fs.rmSync(root,{recursive:true,force:true});}});
